"""Builds claims.json for the ElevenLabs lane. Run from repo root:
python3 -I research/2026-10-20/teardown/elevenlabs/code/build_claims.py"""
import json, os
D = 'data/teardown/elevenlabs/'
T = 'research/2026-10-20/teardown/elevenlabs/'
DATE = '2026-10-20'
C = []
def c(dim, claim, grade, *evidence):
    C.append({'id': 'EL-%02d' % (len(C) + 1), 'dimension': dim, 'claim': claim, 'grade': grade, 'evidence': list(evidence), 'date': DATE})

# 1. Product surface
c('surface', 'The docs index lists 804 pages: 368 ElevenAgents, 404 API reference, 432 help-center, 40 Reception.ai, 66 ElevenAPI, 43 overview; we saved 258 agents/Reception.ai/overview pages as Markdown.', 'observed', D + 'docs/llms.txt', D + '_pages.txt')
c('surface', 'ElevenAgents surfaces documented: builder (prompt, workflows graph, free-form and structured procedures, knowledge base/RAG, tools: client, webhook, code, MCP, system tools), voice (multi-voice, pronunciation dictionaries, expressive mode, audio environment), channels (widget, web/mobile SDKs, WhatsApp, SMS, Slack, Telegram, Teams, custom channel), telephony (Twilio native, Exotel native, SIP trunk, Vonage, CCaaS: Genesys, Five9, Amazon Connect), operate (versioning with branches/merge proposals, environments, experiments, agent testing and simulation, analytics, Spotlight, real-time monitoring, alerts, triage tickets, OpenTelemetry traces, CLI, hosted MCP), privacy (retention, audio saving, redaction, Zero Retention Mode) and legal pages (HIPAA, TCPA, disclosure).', 'observed', D + 'docs/llms.txt', D + '_pages.txt')
c('surface', 'ElevenAgents Architect is an in-product LLM assistant that investigates conversations, edits an agent on a branch, writes and runs tests, and opens a merge proposal; it cannot review/merge, has no scheduled or background work yet, and acts as the user.', 'observed', D + 'docs-md/eleven-agents__operate__architect__proposals.md', D + 'docs-md/eleven-agents__operate__architect__faq.md')
c('surface', 'Reception.ai is a separate SMB product on the same docs site: AI receptionist with scheduling (services, staff, locations, booking page), a client list, orders, quote requests, SMS notifications and its own plans; US/Canada numbers, other countries via a regulatory request.', 'observed', D + 'docs-md/reception-ai__overview.md', D + 'docs-md/reception-ai__phone-numbers__international-numbers.md')
c('surface', 'Outbound at scale in the public product is Batch Calling: upload CSV/XLS with a mandatory phone_number column (other columns become dynamic variables; language/first_message/system_prompt/voice_id columns override the agent), send now or at one scheduled time in a timezone, test-call one recipient, monitor per-recipient status. Concurrency defaults to min(50% of workspace, 70% of agent) limits; Zero Retention Mode cannot be used with batch calls.', 'observed', D + 'docs-md/eleven-agents__phone-numbers__batch-calls.md')
c('surface', 'The signed-out dashboard bundle carries a generated API client for an unpublished outbound-campaigns product: campaigns submit/pause/resume/stop/progress/calls/export, campaign leads with a suppressLead mutation, an attention queue (resolve/retry), workspace campaign config and a pre-revoke-status check. None of these 23 routes is in the public OpenAPI or docs. Conversation records already carry campaign_id, campaign_lead_id, cold_attempt and conversation_type (initial/retry/callback/redirect).', 'observed', T + 'bundle-endpoints.json', D + 'app-js/_index.json', D + 'openapi/api.elevenlabs.io_openapi.json')
c('surface', 'Inference from EL-06: ElevenLabs is building a lead-level campaign control plane (retries, callbacks, suppression, an exceptions queue) on top of batch calling; the 2026-10-17 parity row "no campaign control plane comparable to Vapi/Bolna" is true of the public product today but is likely to expire.', 'inferred', T + 'bundle-endpoints.json', 'research/2026-10-17/lanes/l4a-competitors/parity.csv')
c('surface', 'The dashboard bundle also references unpublished automations (with schedule-preview and runs), task-agents/task-runs, company-oracle (knowledge sources with ingest), templates (browse, from-agent), cloud-storage-destinations and analytics queries (latency, LLM cost, interruptions, concurrency and queue over time): 326 convai routes in the bundle are absent from the public OpenAPI.', 'observed', T + 'bundle-endpoints.json')
# 2. Docs and API
c('api', 'The public OpenAPI (api.elevenlabs.io/openapi.json, 2.3 MB) has 322 paths and 1,644 schemas; 141 paths are /v1/convai (214 operations incl. speech-engine and flows). Groups: agents 34, knowledge-base 25, conversations 15, MCP servers 8, agent-testing 7, batch-calling 6, triage-tickets 5, phone-numbers 3.', 'observed', D + 'openapi/api.elevenlabs.io_openapi.json', D + '_convai_endpoints.txt')
c('api', 'There is no contacts/leads/CRM object in the public API; the end-user object is a user_id string passed at conversation start, listed by GET /v1/convai/users (exact-match search). Campaign-like state lives only in batch calls (status pending/in_progress/completed/failed/cancelled; recipient status adds dispatched/initiated/voicemail) with a single retry endpoint.', 'observed', D + 'openapi/api.elevenlabs.io_openapi.json', D + 'docs-md/eleven-agents__operate__users.md')
c('api', 'Phone numbers are import-only (POST /v1/convai/phone-numbers accepts Twilio, Exotel or SIP-trunk credentials); ElevenLabs does not sell numbers to ElevenAgents customers. TelephonyProvider enum = twilio, sip_trunk, exotel.', 'observed', D + 'openapi/api.elevenlabs.io_openapi.json')
c('api', 'Each conversation record exposes termination_reason, error {code, reason}, call_result (answered/voicemail/busy/no_answer/failed), per-call SIP messages, queue_wait_secs, main_language, feature usage flags, per-call cost and cost_fiat (USD), LLM/TTS/ASR usage, and an OpenTelemetry trace format. Conversations can be filtered by 40 parameters incl. termination_reasons, tool errors, evaluation and data-collection values, topics and guardrail triggers.', 'observed', D + 'openapi/api.elevenlabs.io_openapi.json')
c('api', 'Agent config defaults in the schema: LLM gemini-2.5-flash, TTS eleven_v4_turbo, ASR provider scribe_realtime (changed from elevenlabs on 2026-06-08), turn model turn_v3, turn_eagerness normal, turn_timeout 7 s, soft-timeout filler default text "Hhmmmm...yeah." (off by default), speculative_turn off.', 'observed', D + 'openapi/api.elevenlabs.io_openapi.json', D + 'changelog/entries/2026-6-8.md')
c('api', 'The LLM enum has 111 values: OpenAI GPT-4o..GPT-6.1, Google Gemini 1.5..4 Argon, Anthropic Claude 3..Opus 5.5, xAI Grok, and ElevenLabs-hosted open models (Qwen3/3.5/3.6, GLM 4.5-Air/5.2, DeepSeek Flash 4.1, Nemotron 3.5 Super VL NVFP4, Watt-tool 8B/70B); custom LLM via chat_completions, responses or websocket APIs; backup-LLM cascade on by default.', 'observed', D + 'openapi/api.elevenlabs.io_openapi.json', D + 'docs-md/eleven-agents__customization__llm.md')
c('api', 'Two first-party speech-to-speech Realtime models (eleven_realtime_v1_mini default, v1_max) are rolling out by workspace; Max is not available in India or Singapore residency; an OpenAI-Realtime-compatible endpoint exists.', 'observed', D + 'docs-md/eleven-agents__customization__realtime-models.md', D + 'pricing/elevenlabs.io_pricing_api.html.txt')
# 3. Architecture
c('architecture', 'Voice sessions from the official client SDK (@elevenlabs/client 1.29.0) default to WebRTC via livekit-client ^2.21.0 against wss://livekit.rtc.elevenlabs.io (EU and India residency have their own livekit.rtc.<region>.residency hosts); text-only, signed-URL and orchestrator sessions use WebSocket wss://api.elevenlabs.io/v1/convai/conversation. React Native needs @livekit/react-native.', 'observed', D + 'sdk-npm-client/unpacked/package/package.json', D + 'sdk-npm-client/unpacked/package/dist/utils/ConnectionFactory.js', D + 'sdk-npm-client/unpacked/package/dist/utils/location.js', D + 'sdk-npm-react-native/unpacked/package/package.json')
c('architecture', 'The data model names LiveKit throughout: authorization methods livekit_token/livekit_token_website, features_usage.is_livekit, a LivekitStackType (standard/static) on SIP numbers, and "Whether a LiveKit SIP outbound trunk is configured" on SIP config.', 'observed', D + 'openapi/api.elevenlabs.io_openapi.json')
c('architecture', 'Inference from EL-16/17 + DNS: ElevenLabs runs its own LiveKit (server and LiveKit SIP) under its own domains on Google Cloud rather than LiveKit Cloud, Pipecat or Vocode; orchestration (turn model, ASR, TTS, LLM routing) is its own.', 'inferred', D + 'net/doh-livekit.rtc.elevenlabs.io.json', D + 'net/gcp-cloud.json', D + 'openapi/api.elevenlabs.io_openapi.json')
c('architecture', 'Every HTTP/WebSocket/LiveKit hostname we resolved (api, api.us, elevenlabs.io, livekit.rtc, and the eu/in/sg residency equivalents) sits in Google Cloud prefixes with scope "global" (global external load balancer anycast), so their backend region is not visible from DNS.', 'observed', D + 'net/gcp-cloud.json', D + 'net/doh-api.elevenlabs.io.json', D + 'net/doh-api.in.residency.elevenlabs.io.json')
c('architecture', 'SIP is regional and visible: sip.rtc.elevenlabs.io resolves to 136.112.48.140 in GCP us-central1; sip.rtc.in.residency.elevenlabs.io to 34.100.197.221 in asia-south1 (Mumbai); EU to europe-west1; SG to asia-southeast1. Static-IP SIP hosts (sip-static.rtc.*) sit in 199.88.252.0/24, which ARIN registers to Eleven Labs Inc; the docs say that /24 spans US, EU, India and Singapore.', 'observed', D + 'net/doh-sip.rtc.elevenlabs.io.json', D + 'net/doh-sip.rtc.in.residency.elevenlabs.io.json', D + 'net/gcp-cloud.json', D + 'net/rdap-199.88.252.34.json', D + 'docs-md/eleven-agents__phone-numbers__sip-trunking.md')
c('architecture', 'Inference from EL-20: a standard (non-Enterprise) Indian customer on SIP has media anchored in Iowa, adding roughly one India-US round trip (~200-250 ms; Azure Central India-East US is 201 ms) to every turn, and is exposed to the TRAI rule that Indian SIP termination needs an Indian server (Plivo states this for Vapi). India residency (Enterprise only) moves SIP to Mumbai.', 'inferred', D + 'net/doh-sip.rtc.elevenlabs.io.json', 'research/2026-10-17/lanes/l8-azure-bench/report.md', 'data/teardown/vapi/docs-md/advanced__sip__plivo.md')
c('architecture', 'One 25 s public demo call on elevenlabs.io/conversational-ai (synthetic caller clip, 2026-10-20 17:56 UTC) used a WebSocket to wss://api.elevenlabs.io/v1/convai/conversation from react_sdk 0.14.0-beta.0 (not WebRTC), agent output pcm_44100, user input pcm_16000, server ping 216-223 ms from our US-East egress; 113 frames received (95 audio, 16 ping), 282 sent (262 user_audio_chunk). The demo agent sends no AI disclosure in its first message ("Hey, how can I help you today?").', 'observed', D + 'demo-call/demo-call-signal.json', D + 'har-sanitized/demo-call.slim.har')
c('architecture', 'Speech stack is first-party: ASR Scribe v2 Realtime (scribe_realtime; scribe_v2_turbo also in enum), TTS Eleven v4 Turbo default (also v4, v3 conversational, flash/turbo v2.5, multilingual v2), own turn-detection model turn_v3, own RAG embeddings (e5_mistral_7b_instruct, multilingual_e5_large_instruct). Only the LLM is third-party by default.', 'observed', D + 'openapi/api.elevenlabs.io_openapi.json')
c('architecture', 'Gemini and Claude agent LLM prices are "aligned with Vertex AI regional pricing ... a 10% increase", and LLM availability is filtered by data residency, so these models are inferred to be called through Google Vertex AI regional endpoints.', 'inferred', D + 'docs-md/eleven-agents__customization__llm.md', D + 'openapi/api.elevenlabs.io_openapi.json')
c('architecture', 'Platform plumbing seen on the signed-out app page: Next.js (Turbopack chunks under elevenlabs.io/app_assets), MobX, Google Identity Toolkit (Firebase Auth) for sign-in, Stripe, hCaptcha, PostHog proxied via /dachshund, VWO, Clarity, Sentry, and a Cloud Function us-central1-xi-labs.cloudfunctions.net/geolocation (GCP project xi-labs).', 'observed', D + 'web/app-sign-in.json', D + 'web/www-agents.json', D + 'har-sanitized/app-sign-in.slim.har')
c('architecture', 'The convai widget core (0.21.0) bundles @fingerprintjs/fingerprintjs 5.x and Preact; the widget fingerprints the browser (inferred use: abuse limiting or anonymous user identity).', 'observed', D + 'sdk-npm-convai-widget-core/unpacked/package/package.json')
c('architecture', 'Job posts (157 open, 2026-10-20): Infrastructure Engineer asks for Kubernetes at scale, strong GCP, GPU clusters for training and inference "across cloud and on-prem"; Research Engineer - Inference names CUDA, Triton, TensorRT, vLLM, SGLang. No job post mentions LiveKit, SIP or WebRTC. India roles: AE Mid-Market, Account Manager, Deployment Strategist Lead (Bangalore preferred), EA India & ME.', 'observed', D + 'jobs/ashby-elevenlabs.json')
